const crypto = require("crypto");
// Node.js's crypto from an npm package: hashes, HMAC, random values, key derivation and the
// errors packages see. Prints what it found; the same package under Node.js prints the same.
module.exports = async function run() {
  try {
    await body();
  } catch (e) {
    process.stdout.write("FAILED " + (e && e.stack || e) + "\n");
  }
};
function err(log, label, fn) {
  try {
    fn();
    log(label, "no error");
  } catch (e) {
    log(label, e.name, e.code, e.message);
  }
}
async function body() {
  const out = [];
  const log = (...a) => out.push(a.join(" "));
  for (const alg of ["md5", "sha1", "sha224", "sha256", "sha384", "sha512", "SHA256", "RSA-SHA1", "sha512-256"]) {
    log("hash", alg, crypto.createHash(alg).update("hello ").update(Buffer.from("world")).digest("hex"));
  }
  log("base64", crypto.createHash("sha256").update("héllo", "utf8").digest("base64"));
  log("latin1 input", crypto.createHash("sha1").update("héllo", "latin1").digest("hex"));
  log("buffer", Buffer.isBuffer(crypto.createHash("md5").update("x").digest()), crypto.createHash("md5").update("x").digest().length);
  const h = crypto.createHash("sha256").update("abc");
  const c = h.copy();
  c.update("def");
  log("copy", h.digest("hex"), c.digest("hex"));
  log("one-shot", crypto.hash("sha1", "abc"), crypto.hash("md5", Buffer.from("abc"), "base64"));
  log("views", crypto.createHash("sha256").update(new Uint8Array([1, 2, 3]).subarray(1)).digest("hex"));
  log("hmac", crypto.createHmac("sha256", "key").update("data").digest("hex"));
  log("hmac buffer key", crypto.createHmac("sha512", Buffer.from("k3y")).update("x").digest("base64url"));
  log("hmac empty key", crypto.createHmac("sha1", "").update("x").digest("hex"));
  const mac = crypto.createHmac("md5", "k");
  mac.update("a");
  log("hmac twice", mac.digest("hex"), JSON.stringify(mac.digest("hex")));
  err(log, "hmac update after", () => mac.update("b"));
  const hd = crypto.createHash("md5");
  hd.digest();
  err(log, "digest twice", () => hd.digest());
  err(log, "update after", () => hd.update("x"));
  err(log, "copy after", () => hd.copy());
  err(log, "bad hash", () => crypto.createHash("nope"));
  err(log, "bad hmac", () => crypto.createHmac("nope", "k"));
  err(log, "no alg", () => crypto.createHash());
  err(log, "bad data", () => crypto.createHash("md5").update(5));
  const streamed = await new Promise((res) => {
    const s = crypto.createHash("sha1");
    s.on("data", (d) => res(d.toString("hex")));
    s.write("str");
    s.end("eam");
  });
  log("stream", streamed);
  log("pbkdf2", crypto.pbkdf2Sync("pw", "salt", 1000, 32, "sha256").toString("hex"));
  log("pbkdf2 async", await new Promise((res, rej) => crypto.pbkdf2("pw", "salt", 1, 16, "sha1", (e, k) => (e ? rej(e) : res(k.toString("hex"))))));
  err(log, "pbkdf2 bad digest", () => crypto.pbkdf2Sync("pw", "salt", 1, 16, "nope"));
  err(log, "pbkdf2 iterations", () => crypto.pbkdf2Sync("pw", "salt", 0, 16, "sha1"));
  log("scrypt", crypto.scryptSync("pw", "salt", 32).toString("hex"));
  log("scrypt opts", crypto.scryptSync("pw", "salt", 16, { N: 1024, r: 4, p: 2 }).toString("hex"), crypto.scryptSync("pw", "salt", 16, { cost: 1024, blockSize: 4, parallelization: 2 }).toString("hex"));
  log("scrypt async", await new Promise((res, rej) => crypto.scrypt("pw", "salt", 8, (e, k) => (e ? rej(e) : res(k.toString("hex"))))));
  err(log, "scrypt params", () => crypto.scryptSync("pw", "salt", 16, { N: 3 }));
  const hk = crypto.hkdfSync("sha256", "key", "salt", "info", 24);
  log("hkdf", hk instanceof ArrayBuffer, Buffer.from(hk).toString("hex"));
  log("hkdf async", await new Promise((res, rej) => crypto.hkdf("sha512", "k", "", "", 8, (e, k) => (e ? rej(e) : res(Buffer.from(k).toString("hex"))))));
  const r = crypto.randomBytes(32);
  log("randomBytes", Buffer.isBuffer(r), r.length, r.some((b) => b !== 0));
  log("randomBytes async", await new Promise((res) => crypto.randomBytes(8, (e, b) => res(b.length))));
  err(log, "randomBytes -1", () => crypto.randomBytes(-1));
  err(log, "randomBytes x", () => crypto.randomBytes("x"));
  const filled = crypto.randomFillSync(new Uint32Array(4), 1, 2);
  log("randomFillSync", filled[0], filled.length);
  log("randomFill", await new Promise((res) => crypto.randomFill(Buffer.alloc(6), (e, b) => res(b.length))));
  let inRange = true;
  for (let i = 0; i < 1000; i++) {
    const n = crypto.randomInt(3, 9);
    if (n < 3 || n >= 9 || !Number.isInteger(n)) inRange = false;
  }
  log("randomInt", inRange, crypto.randomInt(1) === 0);
  log("randomInt async", await new Promise((res) => crypto.randomInt(10, (e, n) => res(n >= 0 && n < 10))));
  err(log, "randomInt order", () => crypto.randomInt(5, 2));
  const uuid = crypto.randomUUID();
  log("randomUUID", /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid), uuid !== crypto.randomUUID());
  log("getRandomValues", crypto.getRandomValues(new Uint16Array(4)).length, globalThis.crypto.getRandomValues(new Uint8Array(3)).length);
  err(log, "getRandomValues float", () => crypto.getRandomValues(new Float32Array(2)));
  err(log, "getRandomValues quota", () => crypto.getRandomValues(new Uint8Array(70000)));
  log("global uuid", /^[0-9a-f-]{36}$/.test(globalThis.crypto.randomUUID()));
  log("timingSafeEqual", crypto.timingSafeEqual(Buffer.from("abc"), Buffer.from("abc")), crypto.timingSafeEqual(Buffer.from("abc"), Buffer.from("abd")));
  err(log, "timingSafeEqual length", () => crypto.timingSafeEqual(Buffer.from("a"), Buffer.from("ab")));
  const sd = await crypto.webcrypto.subtle.digest("SHA-256", new TextEncoder().encode("abc"));
  log("subtle.digest", sd instanceof ArrayBuffer, Buffer.from(sd).toString("hex"));
  log("getHashes", crypto.getHashes().includes("sha256"), crypto.getHashes().includes("md5"));
  log("constants", typeof crypto.constants.RSA_PKCS1_PADDING);
  process.stdout.write(out.join("\n") + "\n");
}
